    score,
    maxScore: 100,
    measuredValueLabel: "cpu_load_percent",
    measuredValue: Math.round(loadPercent),
    durationMs,
    evidence: `os.loadavg(): ${loadAvg.toFixed(2)} / ${cpuCores} cores = ${loadPercent.toFixed(1)}% load`,
