import os from "os";

export function scoreProcessHeap(heapPercent: number): { score: number; passed: boolean } {
  const score = heapPercent < 50 ? 100 : heapPercent < 65 ? 88 : heapPercent < 75 ? 72 : heapPercent < 85 ? 55 : heapPercent < 92 ? 38 : 20;
  return { score, passed: heapPercent < 90 };
}

export function scoreCpuLoad(loadPercent: number): { score: number; passed: boolean } {
  const score = loadPercent < 30 ? 100 : loadPercent < 50 ? 88 : loadPercent < 65 ? 72 : loadPercent < 80 ? 55 : loadPercent < 90 ? 38 : 20;
  return { score, passed: loadPercent < 90 };
}

export function scoreFreeMemoryMb(freeMemMb: number): { score: number; passed: boolean } {
  const score = freeMemMb > 1024 ? 100 : freeMemMb > 512 ? 88 : freeMemMb > 256 ? 72 : freeMemMb > 128 ? 55 : freeMemMb > 64 ? 38 : 20;
  return { score, passed: freeMemMb > 64 };
}

export function scoreUptimeMinutes(uptimeMin: number): { score: number; passed: boolean } {
  const score = uptimeMin > 60 ? 100 : uptimeMin > 30 ? 88 : uptimeMin > 10 ? 72 : uptimeMin > 5 ? 58 : uptimeMin > 1 ? 45 : 30;
  return { score, passed: true };
}

export async function testProcessMemory() {
  const id = "process_memory";
  const start = Date.now();
  const mem = process.memoryUsage();
  const heapUsedMb = mem.heapUsed / 1024 / 1024;
  const heapTotalMb = mem.heapTotal / 1024 / 1024;
  const heapPercent = (mem.heapUsed / mem.heapTotal) * 100;
  const durationMs = Date.now() - start;
  const { score, passed } = scoreProcessHeap(heapPercent);

  return {
    testId: id,
    testName: "Process Heap Usage",
    dimension: "System Health",
    passed,
    score,
    maxScore: 100,
    measuredValueLabel: "heap_percent",
    measuredValue: Math.round(heapPercent),
    durationMs,
    evidence: `process.memoryUsage(): heapUsed=${heapUsedMb.toFixed(0)}MB / heapTotal=${heapTotalMb.toFixed(0)}MB = ${heapPercent.toFixed(1)}%`,
  };
}

export async function testCPULoad() {
  const id = "cpu_load";
  const start = Date.now();
  const cpuCores = os.cpus().length;
  const loadAvg = os.loadavg()[0];
  const loadPercent = Math.min(100, (loadAvg / cpuCores) * 100);
  const durationMs = Date.now() - start;
  const { score, passed } = scoreCpuLoad(loadPercent);

  return {
    testId: id,
    testName: "CPU Load Average",
    dimension: "System Health",
    passed,
    score,
    maxScore: 100,
    measuredValueLabel: "cpu_load_percent",
    measuredValue: Math.round(loadPercent),
    durationMs,
    evidence: `os.loadavg(): ${loadAvg.toFixed(2)} / ${cpuCores} cores = ${loadPercent.toFixed(1)}% load`,
  };
}

export async function testOSFreeMemory() {
  const id = "os_freemem";
  const start = Date.now();
  const freeMemMb = os.freemem() / 1024 / 1024;
  const totalMemMb = os.totalmem() / 1024 / 1024;
  const usedPercent = ((totalMemMb - freeMemMb) / totalMemMb) * 100;
  const durationMs = Date.now() - start;
  const { score, passed } = scoreFreeMemoryMb(freeMemMb);

  return {
    testId: id,
    testName: "OS Free Memory",
    dimension: "System Health",
    passed,
    score,
    maxScore: 100,
    measuredValueLabel: "free_mem_mb",
    measuredValue: Math.round(freeMemMb),
    durationMs,
    evidence: `os.freemem()=${freeMemMb.toFixed(0)}MB free / total=${totalMemMb.toFixed(0)}MB (${usedPercent.toFixed(0)}% used)`,
  };
}

export async function testUptimeStability() {
  const id = "uptime_stability";
  const start = Date.now();
  const uptimeSec = process.uptime();
  const uptimeMin = uptimeSec / 60;
  const durationMs = Date.now() - start;
  const { score, passed } = scoreUptimeMinutes(uptimeMin);

  return {
    testId: id,
    testName: "Process Uptime Stability",
    dimension: "System Health",
    passed,
    score,
    maxScore: 100,
    measuredValueLabel: "uptime_minutes",
    measuredValue: Math.round(uptimeMin),
    durationMs,
    evidence: `process.uptime()=${uptimeSec.toFixed(0)}s = ${uptimeMin.toFixed(1)} minutes continuous uptime`,
  };
}

/**
 * HYB-014 historical merge gate.
 *
 * Reports duplicate workspace roots, stale app references, secret-shaped
 * tracked paths, and the status of typecheck, tests, build, and audit.
 * Static checks run by default. Pass --run-suite to execute the four
 * workspace commands and record their exit status. Does not edit CI workflows.
 *
 * Usage: node scripts/historical-merge-gate.mjs [--run-suite]
 */
import { spawnSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

const STALE_APP_PATTERNS = [
  /artifacts\/vitality-supply\b/,
  /artifacts\/vitality-storefront\b/,
  /artifacts\/storefront\b/,
  /projects\/vitality-chems-storefront\b/,
  /@workspace\/vitality-supply\b/,
  /@workspace\/vitality-storefront\b/,
];

const ACTIVE_TEXT_FILES = [
  "pnpm-workspace.yaml",
  "package.json",
  "scripts/dev-unified.mjs",
  "scripts/build-unified.mjs",
  "scripts/test-unified.mjs",
  "scripts/suite-policy.mjs",
];

const SECRET_PATH = [
  /(^|\/)\.env($|\.)/,
  /(^|\/).+\.pem$/,
  /(^|\/).+\.key$/,
  /(^|\/)credentials[^/]*\.json$/,
  /(^|\/)secrets[^/]*\.json$/,
  /(^|\/)service-account[^/]*\.json$/,
  /(^|\/)id_rsa$/,
];

function workspacePatterns() {
  const text = readFileSync(join(root, "pnpm-workspace.yaml"), "utf8");
  const patterns = [];
  let inPackages = false;
  for (const line of text.split("\n")) {
    if (line.startsWith("packages:")) {
      inPackages = true;
      continue;
    }
    if (!inPackages) continue;
    if (/^\S/.test(line)) break;
    const match = line.match(/^\s+-\s+(\S+)\s*$/);
    if (match) patterns.push(match[1]);
  }
  return patterns;
}

function expandPattern(pattern) {
  if (!pattern.includes("*")) {
    return existsSync(join(root, pattern, "package.json")) ? [pattern] : [];
  }
  const dir = pattern.replace(/\/\*$/, "");
  const absolute = join(root, dir);
  if (!existsSync(absolute)) return [];
  return readdirSync(absolute, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && existsSync(join(absolute, entry.name, "package.json")))
    .map((entry) => `${dir}/${entry.name}`);
}

export function duplicateWorkspaceRoots() {
  const seen = new Map();
  for (const pattern of workspacePatterns()) {
    for (const path of expandPattern(pattern)) {
      const prior = seen.get(path);
      if (prior) prior.push(pattern);
      else seen.set(path, [pattern]);
    }
  }
  return [...seen.entries()]
    .filter(([, patterns]) => patterns.length > 1)
    .map(([path, patterns]) => `${path} (${patterns.join(", ")})`);
}

function activeManifests() {
  const files = [...ACTIVE_TEXT_FILES];
  for (const dir of ["artifacts", "lib", "scripts"]) {
    const absolute = join(root, dir);
    if (!existsSync(absolute)) continue;
    for (const entry of readdirSync(absolute, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const manifest = join(dir, entry.name, "package.json");
      if (existsSync(join(root, manifest))) files.push(manifest);
    }
  }
  return files;
}

export function staleAppReferences() {
  const hits = [];
  for (const relative of activeManifests()) {
    const text = readFileSync(join(root, relative), "utf8");
    for (const pattern of STALE_APP_PATTERNS) {
      if (pattern.test(text)) hits.push(`${relative}: ${pattern.source}`);
    }
  }
  return hits;
}

export function secretShapedPaths() {
  const listed = spawnSync("git", ["ls-files", "-z"], { cwd: root, encoding: "utf8" });
  if (listed.status !== 0) {
    throw new Error(listed.stderr || "git ls-files failed");
  }
  const paths = listed.stdout.split("\0").filter(Boolean);
  return paths.filter((path) => {
    if (path === ".env.example" || path.endsWith("/.env.example")) return false;
    return SECRET_PATH.some((pattern) => pattern.test(path));
  });
}

function runCommand(title, command, args) {
  const result = spawnSync(command, args, { cwd: root, encoding: "utf8", stdio: "inherit" });
  const status = result.status === 0 ? "pass" : "fail";
  return `${title}: ${status}`;
}

export function renderReport({ runSuite }) {
  const duplicates = duplicateWorkspaceRoots();
  const stale = staleAppReferences();
  const secrets = secretShapedPaths();
  const lines = [
    "historical-merge-gate",
    `duplicate_workspace_roots: ${duplicates.length}`,
    ...duplicates.map((item) => `  - ${item}`),
    `stale_app_references: ${stale.length}`,
    ...stale.map((item) => `  - ${item}`),
    `secret_shaped_paths: ${secrets.length}`,
    ...secrets.map((item) => `  - ${item}`),
  ];
  if (runSuite) {
    lines.push(runCommand("typecheck", "pnpm", ["run", "typecheck"]));
    lines.push(runCommand("test", "pnpm", ["test"]));
    lines.push(runCommand("build", "pnpm", ["run", "build"]));
    lines.push(runCommand("audit", "pnpm", ["audit"]));
  } else {
    lines.push("typecheck: not-run");
    lines.push("test: not-run");
    lines.push("build: not-run");
    lines.push("audit: not-run");
    lines.push("suite: pass --run-suite to execute typecheck, test, build, and audit");
  }
  return {
    text: `${lines.join("\n")}\n`,
    ok: duplicates.length === 0 && stale.length === 0 && secrets.length === 0,
  };
}

function invokedDirectly() {
  const entry = process.argv[1];
  return entry !== undefined && import.meta.url === pathToFileURL(entry).href;
}

if (invokedDirectly()) {
  const report = renderReport({ runSuite: process.argv.includes("--run-suite") });
  process.stdout.write(report.text);
  if (!report.ok) process.exit(1);
}

/**
 * Repeatable eval record writer.
 *
 * Writes JSON {sha, date_ct, model, suite, n, pass, cost_usd} from measured
 * inputs. It does not run a quiz and does not invent scores. Suite names that
 * claim MMLU or MMLU-Pro are refused: homemade quizzes are not those benchmarks.
 *
 * Usage:
 *   node scripts/eval/write-result.mjs \
 *     --sha <git-sha> --model <name> --suite <name> \
 *     --n <int> --pass <int> --cost-usd <number> [--out <file>]
 */
import { writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const MMLU_NAME = /mmlu/i;

export function assertNotIndustryMmlu(suite) {
  if (typeof suite !== "string" || suite.trim() === "") {
    throw new Error("suite must be a non-empty name");
  }
  if (MMLU_NAME.test(suite)) {
    throw new Error(
      `Refusing suite name ${JSON.stringify(suite)}: homemade quizzes are not MMLU or MMLU-Pro`,
    );
  }
}

export function formatDateCt(date = new Date()) {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", {
      timeZone: "America/Chicago",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(date)
      .map((part) => [part.type, part.value]),
  );
  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second} CT`;
}

export function buildEvalRecord({ sha, dateCt, model, suite, n, pass, costUsd }) {
  if (typeof sha !== "string" || sha.trim() === "") {
    throw new Error("sha is required");
  }
  if (typeof model !== "string" || model.trim() === "") {
    throw new Error("model is required");
  }
  assertNotIndustryMmlu(suite);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("n must be a non-negative integer");
  }
  if (!Number.isInteger(pass) || pass < 0 || pass > n) {
    throw new Error("pass must be an integer from 0 through n");
  }
  if (typeof costUsd !== "number" || !Number.isFinite(costUsd) || costUsd < 0) {
    throw new Error("cost_usd must be a finite number >= 0");
  }
  return {
    sha,
    date_ct: dateCt ?? formatDateCt(),
    model,
    suite,
    n,
    pass,
    cost_usd: costUsd,
  };
}

function readFlag(argv, name) {
  const index = argv.indexOf(name);
  if (index === -1) return undefined;
  return argv[index + 1];
}

export function recordFromArgv(argv, date = new Date()) {
  const n = Number(readFlag(argv, "--n"));
  const pass = Number(readFlag(argv, "--pass"));
  const costUsd = Number(readFlag(argv, "--cost-usd"));
  return buildEvalRecord({
    sha: readFlag(argv, "--sha"),
    dateCt: readFlag(argv, "--date-ct") ?? formatDateCt(date),
    model: readFlag(argv, "--model"),
    suite: readFlag(argv, "--suite"),
    n,
    pass,
    costUsd,
  });
}

function invokedDirectly() {
  const entry = process.argv[1];
  return entry !== undefined && import.meta.url === pathToFileURL(entry).href;
}

if (invokedDirectly()) {
  try {
    const record = recordFromArgv(process.argv.slice(2));
    const json = `${JSON.stringify(record, null, 2)}\n`;
    const out = readFlag(process.argv.slice(2), "--out");
    if (out) writeFileSync(out, json);
    else process.stdout.write(json);
  } catch (error) {
    console.error(`[eval-record] ${error instanceof Error ? error.message : String(error)}`);
    process.exit(1);
  }
}

